program='''def transform(grid):
    h, w = len(grid), len(grid[0])
    forms = (
        lambda r, c: r,
        lambda r, c: c,
        lambda r, c: c - r,
        lambda r, c: c + r,
    )
    candidates = []
    for key in forms:
        observed = {}
        consistent_lines = True
        for r, row in enumerate(grid):
            for c, value in enumerate(row):
                if value:
                    k = key(r, c)
                    if k in observed and observed[k] != value:
                        consistent_lines = False
                        break
                    observed[k] = value
            if not consistent_lines:
                break
        if not consistent_lines:
            continue
        for period in range(1, h + w + 1):
            pattern = {}
            for k, value in observed.items():
                residue = k % period
                if residue in pattern and pattern[residue] != value:
                    break
                pattern[residue] = value
            else:
                if len(pattern) == period:
                    candidates.append((period, key, pattern))
                    break
    if not candidates:
        raise ValueError("Could not infer a complete periodic stripe pattern")
    _, key, pattern = min(candidates, key=lambda item: item[0])
    return [[pattern[key(r, c) % len(pattern)] for c in range(w)] for r in range(h)]
'''
